```ts
import { prisma } from '@/lib/prisma'
import type { Event } from '@prisma/client'

export interface EventRange {
  start?: Date
  end?: Date
}

export interface CreateEventData {
  title: string
  description?: string | null
  start: Date
  end: Date
}

export interface UpdateEventData {
  title?: string
  description?: string | null
  start?: Date
  end?: Date
}

// 조회 범위와 겹치는 이벤트만 반환한다 (start < rangeEnd && end > rangeStart)
export async function listEvents(userId: string, range: EventRange): Promise<Event[]> {
  return prisma.event.findMany({
    where: {
      userId,
      ...(range.start ? { end: { gt: range.start } } : {}),
      ...(range.end ? { start: { lt: range.end } } : {}),
    },
    orderBy: { start: 'asc' },
  })
}

export async function createEvent(userId: string, data: CreateEventData): Promise<Event> {
  return prisma.event.create({
    data: {
      userId,
      title: data.title,
      description: data.description ?? null,
      start: data.start,
      end: data.end,
    },
  })
}

export async function findOwnedEvent(userId: string, id: string): Promise<Event | null> {
  return prisma.event.findFirst({ where: { id, userId } })
}

export async function updateEvent(userId: string, id: string, data: UpdateEventData): Promise<Event | null> {
  const owned = await findOwnedEvent(userId, id)
  if (!owned) return null
  return prisma.event.update({ where: { id }, data })
}

export async function deleteEvent(userId: string, id: string): Promise<boolean> {
  const owned = await findOwnedEvent(userId, id)
  if (!owned) return false
  await prisma.event.delete({ where: { id } })
  return true
}
```

Note: `description` update semantics — if `description` is undefined → don't include in update; if null → clear. In UpdateEventData, `description?: string | null` — passing `data` directly to prisma.update: `{ title?, description?, start?, end? }` — undefined fields are ignored by Prisma. Good.

