export type DragMode = 'move' | 'resize-start' | 'resize-end'

export interface DragPayload { eventId: string; mode: DragMode }

// 모듈 수준 드래그 상태 — jsdom/브라우저 간 dataTransfer 불일치를 보완
let currentDrag: DragPayload | null = null
export function setDragPayload(p: DragPayload | null) { currentDrag = p }
export function getDragPayload(): DragPayload | null { return currentDrag }

export function startOfDay(d: Date): Date { const x = new Date(d); x.setHours(0,0,0,0); return x }
export function endOfDay(d: Date): Date { const x = new Date(d); x.setHours(23,59,59,999); return x }

// 이동: 기간(길이)을 유지한 채 시작일을 target 날짜의 원래 시각으로 이동
export function applyMove(start: Date, end: Date, target: Date): { start: Date; end: Date } {
  const duration = end.getTime() - start.getTime()
  const newStart = new Date(startOfDay(target).getTime() + (start.getTime() - startOfDay(start).getTime()))
  return { start: newStart, end: new Date(newStart.getTime() + duration) }
}
export function applyResizeEnd(start: Date, end: Date, target: Date): { start; end } | null {
  const newEnd = endOfDay(target)  // or target at end's time? use endOfDay — dragging to a day sets end to that day
  if (newEnd.getTime() <= start.getTime()) return null
  return { start: new Date(start), end: newEnd }
}
export function applyResizeStart(start, end, target) | null {
  const newStart = startOfDay(target)
  if (newStart.getTime() >= end.getTime()) return null
  return { start: newStart, end: new Date(end) }
}
```

