export function resolveDropDate(target: HTMLElement, clientX: number, clientY: number): Date | null {
  const direct = target.closest<HTMLElement>('[data-rbc-date]')
  if (direct?.dataset.rbcDate) return parseOrNull(direct.dataset.rbcDate)
  const view = target.closest('.rbc-month-view')
